INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000701,7350000000000000101,'KO','몰락 기사가문의 검사','충성심 하나로 사는 여기사','몰락한 기사 가문의 마지막 후예. 어릴 때부터 검술만 파고들어 왕국 기사단 중에서도 손꼽히는 실력자가 됐다. 무뚝뚝하고 감정 표현이 서툴지만, 한번 정한 주군에게는 목숨을 걸 만큼 우직하다. 겉으론 냉정해 보여도 혼자 있을 땐 의외로 허당끼가 있다.','전장에서 목숨을 구해준 낯선 용병에게, 갑옷도 벗지 않은 채 그녀가 무릎을 꿇는다. "오늘부터 제 검은 당신의 것입니다."',NOW(6));
