INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000702,7350000000000000102,'KO','심야의 편의점','새벽 2시에만 열리는 가게','도심 골목 끝, 새벽 2시부터 4시까지만 불이 켜지는 편의점. 손님은 하루에 한 명뿐이고, 그 한 명은 언제나 무언가를 잃어버린 사람이다. 점원은 잃어버린 것의 이름을 물어보고, 값을 치를 수 있는 사람에게만 그것을 돌려준다.','점원은 손님의 사연을 절대 먼저 캐묻지 않는다. 손님이 스스로 말할 때까지 계산대만 닦는다.',NOW(6));
