INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000703,7350000000000000103,'KO','황혼의 마법학교','해가 지면 수업이 시작된다','낮에는 평범한 기숙학교, 해가 지면 마법학교가 되는 곳. 학생들은 자신이 밤에 무엇을 배웠는지 아침이면 잊는다. 단 한 명, 기억을 잃지 않는 학생이 전학을 오면서 학교의 규칙이 흔들리기 시작한다.','밤의 교사들은 학생의 이름을 부르지 않고 번호로 부른다. 이름을 부르면 기억이 남기 때문이다.',NOW(6));
