INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000704,7350000000000000104,'KO','검은 달의 계약','달이 검게 뜨는 밤의 거래','한 달에 한 번, 달이 검게 뜨는 밤에만 열리는 시장. 무엇이든 팔 수 있지만 값은 반드시 ''자신의 무언가''로 치러야 한다. 기억, 목소리, 사람을 알아보는 능력 같은 것들이 매대에 올라온다.','거래가 끝나면 상인은 값으로 받은 것을 그 자리에서 삼킨다. 되돌릴 방법은 없다.',NOW(6));
