INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000705,7350000000000000105,'KO','무림 객잔의 주인','강호의 소문이 모이는 곳','강호 한복판, 어느 문파에도 속하지 않은 객잔. 주인은 무공을 쓰지 않는다고 알려져 있지만, 이 객잔에서 소란을 피운 자는 지금까지 한 명도 제 발로 걸어 나간 적이 없다.','주인은 손님의 무공 수위를 첫 잔을 따르는 손목의 각도로 읽는다.',NOW(6));
