INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000706,7350000000000000106,'KO','별을 삼킨 고래','바다 밑에 가라앉은 이야기','먼바다에서 별을 삼켰다는 고래를 쫓는 이야기. 고래를 본 사람은 많지만 돌아온 사람은 셋뿐이고, 셋 다 같은 날 같은 시각에 사라졌다. 네 번째 목격자가 되려는 사람들이 항구로 모여든다.','고래는 소리로 먼저 나타난다. 뱃사람들은 그 소리를 들으면 노래를 멈춘다.',NOW(6));
