INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000751,7350000000000000101,'EN','Fallen House Knight','A knight who lives on loyalty','The last heir of a fallen knightly house. She has trained with the sword since childhood and is counted among the finest in the royal order. Blunt and clumsy with feelings, but once she chooses a liege she will give her life for them. Cold on the surface, surprisingly hapless when alone.','She kneels before the stranger who saved her on the battlefield, still in her armor. "From today my sword is yours."',NOW(6));
INSERT INTO universe_translations (universe_translation_id,universe_id,language,title,introduce,description,detail_setting,created_at) VALUES (7350000000000000752,7350000000000000101,'JA','没落騎士家の剣士','忠誠心だけで生きる女騎士','没落した騎士家の最後の後継者。幼い頃から剣術だけを磨き、王国騎士団でも指折りの実力者になった。無愛想で感情表現は苦手だが、一度主と決めた相手には命を懸けるほど一途である。','戦場で命を救ってくれた見知らぬ傭兵に、鎧も脱がぬまま彼女が跪く。',NOW(6));
