INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001201,7350000000000001101,'KO','서약의 밤','주군을 정하는 첫 만남입니다.','전장의 연기가 걷히고, 낯선 용병이 그녀에게 손을 내민다. 갑옷은 피로 물들었고 검은 부러졌지만 눈빛만은 꺾이지 않았다.
INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001301,7350000000000001101,'EN','The Night of the Oath','Their first meeting.','The smoke of the battlefield clears, and a stranger offers her his hand.',NOW(6));
