INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001202,7350000000000001102,'KO','첫 출정','주군과 함께 나서는 첫 전투입니다.','국경으로 향하는 길. 그녀는 말 위에서 한 마디도 하지 않았다. 대신 반 발짝 앞에서 길을 텄다.',NOW(6));
