INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001203,7350000000000001103,'KO','가문의 밤','폐성으로 돌아가는 이벤트 회차입니다.','무너진 성벽 아래에서 그녀가 처음으로 갑옷을 벗는다.',NOW(6));
INSERT INTO scenarios (scenario_id,universe_id,episode_no,version_no,display_order,scenario_type,status,created_at) VALUES (7350000000000001104,7350000000000000101,2,2,2,'NORMAL','DEPRECATED',NOW(6));
INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001204,7350000000000001104,'KO','첫 출정(구)','2화의 이전 버전입니다.','국경으로 향하는 길. 그녀는 계속 말이 없었다.',NOW(6));
INSERT INTO scenarios (scenario_id,universe_id,episode_no,version_no,display_order,scenario_type,status,created_at) VALUES (7350000000000001105,7350000000000000102,1,1,1,'START','ACTIVE',NOW(6));
INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001205,7350000000000001105,'KO','새벽 2시','가게 문이 열리는 첫 회차입니다.','셔터가 반쯤 올라가고, 형광등이 두 번 깜빡인 뒤 켜진다. 오늘의 손님이 문 앞에 서 있다.',NOW(6));
INSERT INTO scenarios (scenario_id,universe_id,episode_no,version_no,display_order,scenario_type,status,created_at) VALUES (7350000000000001106,7350000000000000103,1,1,1,'START','ACTIVE',NOW(6));
INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001206,7350000000000001106,'KO','전학 첫날','기억을 잃지 않는 학생이 도착합니다.','교문을 넘자 해가 졌다. 아무도 이상하게 여기지 않는다는 것이 가장 이상했다.',NOW(6));
INSERT INTO scenarios (scenario_id,universe_id,episode_no,version_no,display_order,scenario_type,status,created_at) VALUES (7350000000000001107,7350000000000000106,1,1,1,'START','ACTIVE',NOW(6));
INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001207,7350000000000001107,'KO','네 번째 목격자','항구에 모인 사람들의 첫 밤입니다.','항구의 불이 하나씩 꺼진다. 누군가 "들린다"고 말했고, 술집 안의 노래가 멈췄다.',NOW(6));
INSERT INTO scenarios (scenario_id,universe_id,episode_no,version_no,display_order,scenario_type,status,created_at) VALUES (7350000000000001108,7350000000000000106,2,1,2,'NORMAL','ACTIVE',NOW(6));
INSERT INTO scenario_translations (scenario_translation_id,scenario_id,language,title,description,content,created_at) VALUES (7350000000000001208,7350000000000001108,'KO','첫 출항','고래를 쫓아 바다로 나갑니다.','배가 항구를 벗어나자 소리는 더 또렷해졌다.',NOW(6));
